export interface ManualModelAliasEntry { alias: string; targetModel: string; }

export async function replaceManualAliasesForTarget(
  settingsService: ISettingsService,
  targetModel: string,
  aliases: string[],
): Promise<ManualModelAliasEntry[]>

export async function retargetManualAliases(
  settingsService: ISettingsService,
  previousModelName: string,
  nextModelName: string,
): Promise<void>

app.put("/models/:name/aliases", async (req, res) => {
  const aliases = aliasListSchema.parse(req.body).aliases;
  const updated = await replaceManualAliasesForTarget(settingsService, req.params.name, aliases);
  res.json({ aliases: updated });
});

export async function updateModelAliases(modelName: string, aliases: string[]): Promise<{ aliases: ManualModelAliasEntry[] }> {
  return fetchApi(`/models/${encodeURIComponent(modelName)}/aliases`, {
    method: "PUT",
    body: JSON.stringify({ aliases })
  });
}

interface ModelAliasesEditorProps {
  aliases: string[];
  onChange: (aliases: string[]) => void;
}
